                for dr,dc in ((0,0),(0,1),(1,0),(1,1)):
                    a,b=r+dr,c+dc
                    O[a,b]=1; marked.add((a,b)); continue
            elif True:  # skip old else clause with syntax error
                pass
            else:
                rs=[p[0] for p in comp]; cls=[p[1] for p in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cls),max(cls)
                roles=Counter(('tl'if p==(r0,c0)else'tr'if p==(r0,c1)else'bl'if p==(r1,c0)else'br') for p in comp)
                col=max(roles.items(), key=lambda kv:(kv[1], min(kv[0])))[0]
                col=CORNER.get(col,col)
                for p in comp:
                    if p not in marked:
                        O[p]=col; marked.add(p)
