import os,glob,re,json
def load(p):
    t=open(p, errors='ignore').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair (\d+) (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        start=m.end()
        rows=[r.split() for r in t[start:].split('\n')[:h]]
        # discard the header line if it leaked: first row should not contain "x" or be the dim line
        rows=[r for r in rows if 'x' not in r and len(r)==w]
        if all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
